import Foundation
import Testing

@testable import GlintLicensing

/// Tokens signed by the license server (server/license, a Cloudflare Worker) must verify in
/// the app, and keys signed by the app's tooling must verify on the server. The fixture is
/// generated by `npm run fixture` in server/license with a published TEST key; the Worker's
/// vitest suite checks the other direction against the same file.
@Suite("License server compatibility")
struct LicenseServerCompatibilityTests {
    struct Fixture: Decodable {
        let publicKeyBase64: String
        let installID: String
        let workerLicenseKey: String
        let workerActivationToken: String
        let swiftLicenseKey: String
    }

    let fixture: Fixture

    init() throws {
        let url = try #require(Bundle.module.url(forResource: "worker-tokens", withExtension: "json", subdirectory: "Fixtures"))
        fixture = try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    var verifier: LicenseVerifier {
        get throws { try LicenseVerifier(publicKeyBase64: fixture.publicKeyBase64) }
    }

    @Test func workerLicenseKeyVerifies() throws {
        let payload = try verifier.verify(fixture.workerLicenseKey, kind: .license)
        #expect(payload.product == LicensePayload.currentProduct)
        #expect(payload.emailHash == LicensePayload.hashEmail("Buyer@Example.com"))
        #expect(payload.installID == nil)
    }

    @Test func workerActivationTokenIsBoundToItsInstall() throws {
        let payload = try verifier.verify(fixture.workerActivationToken, kind: .activation, installID: fixture.installID)
        #expect(payload.kind == .activation)
        #expect(payload.installID == fixture.installID)
        #expect(throws: LicenseError.wrongDevice) {
            _ = try verifier.verify(fixture.workerActivationToken, kind: .activation, installID: "ANOTHER-MAC")
        }
    }

    @Test func workerPayloadBytesMatchTheAppsEncoder() throws {
        // Re-encoding the decoded payload must reproduce the server's bytes exactly, so both
        // sides agree on the canonical form (sorted keys, integer seconds).
        for token in [fixture.workerLicenseKey, fixture.workerActivationToken, fixture.swiftLicenseKey] {
            let parts = try #require(LicenseTokenCodec.split(token))
            let payload = try LicenseTokenCodec.decodePayload(parts.payload)
            #expect(try LicenseTokenCodec.encodePayload(payload) == parts.payload)
        }
    }

    @Test func licenseManagerAcceptsTheServersActivation() async throws {
        let store = InMemorySecureStore()
        try store.setString(fixture.installID, for: InstallID.key)
        let service = FixtureActivationService(token: fixture.workerActivationToken)
        let manager = await LicenseManager(verifier: try verifier, store: store, activationService: service)
        try await manager.activate(key: fixture.workerLicenseKey)
        #expect(await manager.entitlements.isLicensed)
    }
}

private struct FixtureActivationService: ActivationService {
    let token: String

    func activate(key: String, installID: String) async throws -> String { token }
    func deactivate(activationToken: String, installID: String) async throws {}
    func isRevoked(activationToken: String) async throws -> Bool { false }
}
